initJs:
function(container, apiUrl, tables) {
  let currentStoreId = '';
  let selectedOrders = new Set();
  let allOrders = [];

  // テーブル再描画関数
  function renderOrders(orders) {
    const tbody = container.querySelector('#order-tbody');
    const noDataMessage = container.querySelector('#no-data-message');
    const sendBtn = container.querySelector('#btn-send');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.classList.remove('hidden');
      sendBtn.disabled = true;
      return;
    }

    noDataMessage.classList.add('hidden');

    tbody.innerHTML = orders.map(order => {
      const statusClass = order.発注ステータス === '送信済み' ? 'status-sent' : 
                         order.発注ステータス === 'エラー' ? 'status-error' : 'status-pending';
      const isDisabled = order.発注ステータス === '送信済み' ? 'disabled' : '';
      const isChecked = selectedOrders.has(order.id) ? 'checked' : '';

      return `
        <tr data-id="${order.id}">
          <td>
            <input type="checkbox" class="individual-checkbox" data-id="${order.id}" ${isChecked} ${isDisabled}>
          </td>
          <td>${order.商品コード || ''}</td>
          <td>${order.商品名 || ''}</td>
          <td class="text-right">${order.予測数量 ? order.予測数量.toLocaleString() : ''}</td>
          <td class="text-right">${order.発注数量 ? order.発注数量.toLocaleString() : ''}</td>
          <td>${order.仕入先名 || ''}</td>
          <td class="text-right">¥${order.発注金額 ? order.発注金額.toLocaleString() : '0'}</td>
          <td><span class="status-badge ${statusClass}">${order.発注ステータス || '送信待ち'}</span></td>
        </tr>
      `;
    }).join('');

    updateSendButton();
  }

  // 店舗選択ドロップダウンを初期化
  async function initStoreSelect() {
    const storeSelect = container.querySelector('#store-select');
    const stores = await window.aivicApi.list(1); // 店舗マスタ

    if (stores) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.filter(store => store.有効フラグ).map(store => 
          `<option value="${store.id}">${store.店舗名}</option>`
        ).join('');
    }
  }

  // 発注データを店舗で絞り込み
  async function loadOrdersByStore(storeId) {
    if (!storeId) {
      renderOrders([]);
      return;
    }

    const orders = await window.aivicApi.list(7); // 発注データ
    if (orders) {
      const filteredOrders = orders.filter(order => order.店舗ID === storeId);

      // 商品情報と仕入先情報を結合
      const products = await window.aivicApi.list(2); // 商品マスタ
      const predictions = await window.aivicApi.list(6); // 需要予測結果

      const enrichedOrders = filteredOrders.map(order => {
        const product = products?.find(p => p.id === order.商品ID);
        const prediction = predictions?.find(p => p.id === order.需要予測結果ID);

        return {
          ...order,
          商品コード: product?.商品コード || '',
          商品名: product?.商品名|| '',
          仕入先名: '仕入先A', // 実際は仕入先マスタから取得
          予測数量: prediction?.予測数量 || 0
        };
      });

      allOrders = enrichedOrders;
      renderOrders(enrichedOrders);
    }
  }

  // 送信ボタンの状態更新
  function updateSendButton() {
    const sendBtn = container.querySelector('#btn-send');
    const hasSelection = selectedOrders.size > 0;
    sendBtn.disabled = !hasSelection;
    sendBtn.textContent = hasSelection ? `選択した${selectedOrders.size}件の発注を送信` : '選択した発注を送信';
  }

  // 全選択チェックボックスの処理
  function handleSelectAll() {
    const selectAllCheckbox = container.querySelector('#select-all');
    const individualCheckboxes = container.querySelectorAll('.individual-checkbox:not([disabled])');

    if (selectAllCheckbox.checked) {
      selectedOrders.clear();
      individualCheckboxes.forEach(cb => {
        selectedOrders.add(cb.dataset.id);
        cb.checked = true;
      });
    } else {
      selectedOrders.clear();
      individualCheckboxes.forEach(cb => {
        cb.checked = false;
      });
    }

    updateSendButton();
  }

  // 個別選択チェックボックスの処理
  function handleIndividualSelect(checkbox) {
    const orderId = checkbox.dataset.id;

    if (checkbox.checked) {
      selectedOrders.add(orderId);
    } else {
      selectedOrders.delete(orderId);
    }

    // 全選択チェックボックスの状態更新
    const selectAllCheckbox = container.querySelector('#select-all');
    const totalCheckboxes = container.querySelectorAll('.individual-checkbox:not([disabled])').length;
    selectAllCheckbox.checked = selectedOrders.size === totalCheckboxes && totalCheckboxes > 0;

    updateSendButton();
  }

  // 発注送信処理
  async function sendOrders() {
    if (selectedOrders.size === 0) {
      showMessage('発注対象が選択されていません', 'error');
      return;
    }

    // 確認ダイアログ表示
    const confirmDialog = container.querySelector('#confirm-dialog');
    const confirmMessage = container.querySelector('#confirm-message');
    confirmMessage.textContent = `選択した${selectedOrders.size}件の発注データを送信しますか？`;
    confirmDialog.classList.remove('hidden');
  }

  // 実際の送信処理
  async function executeSend() {
    const confirmDialog = container.querySelector('#confirm-dialog');
    confirmDialog.classList.add('hidden');

    let successCount = 0;
    let errorCount = 0;

    try {
      // 選択された発注データを送信済みに更新
      for (const orderId of selectedOrders) {
        const updated = await window.aivicApi.update(7, orderId, {
          発注ステータス: '送信済み',
          更新日時: new Date().toISOString()
        });

        if (updated) {
          successCount++;
        } else {
          errorCount++;
          // 通信エラーの場合はエラーステータスに更新
          await window.aivicApi.update(7, orderId, {
            発注ステータス: 'エラー',
            更新日時: new Date().toISOString()
          });
        }
      }

      if (successCount > 0) {
        showMessage(`${successCount}件の発注データの送信が完了しました`, 'success');
      }
      if (errorCount > 0) {
        showMessage(`${errorCount}件の発注データの送信に失敗しました`, 'error');
      }

      // 選択をクリアして再読み込み
      selectedOrders.clear();
      const selectAllCheckbox = container.querySelector('#select-all');
      selectAllCheckbox.checked = false;

      await loadOrdersByStore(currentStoreId);

    } catch (error) {
      showMessage('通信エラーが発生しました。ネットワーク接続を確認してください。', 'error');
    }
  }

  // メッセージ表示
  function showMessage(text, type) {
    const messageArea = container.querySelector('#message-area');
    messageArea.textContent = text;
    messageArea.className = `message-${type}`;
    messageArea.classList.remove('hidden');

    setTimeout(() => {
      messageArea.classList.add('hidden');
    }, 5000);
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 店舗選択
    const storeSelect = container.querySelector('#store-select');
    storeSelect.addEventListener('change', async (e) => {
      currentStoreId = e.target.value;
      selectedOrders.clear();
      const selectAllCheckbox = container.querySelector('#select-all');
      selectAllCheckbox.checked = false;
      await loadOrdersByStore(currentStoreId);
    });

    // 全選択チェックボックス
    const selectAllCheckbox = container.querySelector('#select-all');
    selectAllCheckbox.addEventListener('change', handleSelectAll);

    // 送信ボタン
    const sendBtn = container.querySelector('#btn-send');
    sendBtn.addEventListener('click', sendOrders);

    // 確認ダイアログ
    const confirmOk = container.querySelector('#confirm-ok');
    const confirmCancel = container.querySelector('#confirm-cancel');
    const confirmDialog = container.querySelector('#confirm-dialog');

    confirmOk.addEventListener('click', executeSend);
    confirmCancel.addEventListener('click', () => {
      confirmDialog.classList.add('hidden');
    });

    // イベントデリゲーション（個別チェックボックス）
    container.addEventListener('change', (e) => {
      if (e.target.classList.contains('individual-checkbox')) {
        handleIndividualSelect(e.target);
      }
    });
  }

  // 初期化
  async function init() {
    await initStoreSelect();
    setupEventListeners();

    // 初期データ表示（店舗未選択時は空）
    renderOrders([]);
  }

  init();
}
